export class BattleAudio{
 constructor(){this.enabled=false;this.musicEnabled=true;this.music=new Audio('assets/audio/battle.mp3');this.music.loop=true;this.music.volume=.12;this.cries=new Map();this.buffers=new Map();this.active=new Set()}
 async enable(){this.ctx??=new AudioContext();await this.ctx.resume();this.enabled=true}
 disable(){this.enabled=false;this.music.pause();for(const a of this.active)a.pause();this.active.clear()}
 background(on){this.battling=on;if(on&&this.enabled&&this.musicEnabled)this.music.play().catch(()=>{});else this.music.pause()}
 async cry(id,bundled){if(!this.enabled)return;let a=this.cries.get(id);if(!a){a=new Audio(bundled?`assets/audio/${id}.ogg`:`https://raw.githubusercontent.com/PokeAPI/cries/main/cries/pokemon/latest/${id}.ogg`);a.volume=.2;this.cries.set(id,a)}a.currentTime=0;this.active.add(a);a.onended=()=>this.active.delete(a);a.play().catch(()=>this.active.delete(a))}
 pause(on){if(on){this.music.pause();for(const a of this.active)a.pause();this.ctx?.suspend()}else{if(this.enabled){this.ctx?.resume();this.background(this.battling)}}}
 sfx(type,phase='attack'){if(!this.enabled||!this.ctx)return;const c=this.ctx,t=c.currentTime,g=c.createGain();g.connect(c.destination);const physical=['normal','fighting','rock','ground','steel'].includes(type),duration=phase==='impact'?.15:.35;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.055,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+duration);if(physical||['fire','water','flying'].includes(type)){const n=c.createBuffer(1,c.sampleRate*duration,c.sampleRate),d=n.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1);const source=c.createBufferSource(),filter=c.createBiquadFilter();source.buffer=n;filter.type='lowpass';filter.frequency.setValueAtTime(physical?850:2600,t);filter.frequency.exponentialRampToValueAtTime(100,t+duration);source.connect(filter).connect(g);source.start(t);source.stop(t+duration)}const o=c.createOscillator();o.type=type==='electric'?'sawtooth':'sine';o.frequency.setValueAtTime(phase==='impact'?100:type==='electric'?650:220,t);o.frequency.exponentialRampToValueAtTime(phase==='impact'?35:800,t+duration);o.connect(g);o.start(t);o.stop(t+duration)}
}
